#!/usr/bin/env python3
"""Isolated editorial proposals for remaining 53 Recognition KU risks, source safe."""
import json,pathlib,collections
B=pathlib.Path(__file__).resolve().parent; D=B/"teaching_qa/full_recognition_audit"
read=lambda p:[json.loads(x) for x in (D/p).read_text(encoding="utf-8").splitlines() if x.strip()]
cases=read("remaining_53_review_dossier.jsonl")
clues={int(k):v for k,v in json.loads("{\"2\":\"a document presenting findings or information, often submitted to an authority or organization\",\"3\":\"something placed over an object to conceal or protect it\",\"5\":\"holding the highest rank or authority within a group\",\"6\":\"a problem that requires effort or skill to overcome\",\"7\":\"be situated or located in a particular position\",\"9\":\"make a solemn declaration or oath that something is true\",\"10\":\"state confidently and forcefully that something is true\",\"11\":\"a broad statement drawn from multiple particular examples\",\"15\":\"famous and highly respected for achievements\",\"17\":\"a person who prepares approximate cost estimates for work or materials\",\"22\":\"the particular arrangement or layout of components in a system\",\"24\":\"in an ingenious or skillful way\",\"27\":\"relating to a person between thirteen and nineteen years old; often informal\",\"28\":\"relating to the teenage years, typically ages thirteen through nineteen\",\"30\":\"lacking knowledge or education in a particular subject\",\"43\":\"having moods that change frequently; prone to sulking\",\"44\":\"give an advance indication of a future event\",\"45\":\"an exclamation expressing regret or sorrow\",\"46\":\"the equipment or cargo carried by a vehicle, aircraft, or rocket\",\"48\":\"an insulting informal noun for a contemptible person\",\"51\":\"a contemptible person; also the name of a black-and-white mammal\",\"54\":\"the act of watching or examining something\",\"56\":\"a set of three, especially three offspring born at one birth\",\"57\":\"boldly daring, sometimes recklessly so\",\"59\":\"embarrassment or distress arising from failure or disappointment\",\"61\":\"an uncontrolled pouring out or expression of words or feelings\",\"62\":\"noisy, boastful speech or behavior intended to intimidate\",\"63\":\"waterlogged or resembling a marsh\",\"73\":\"causing harm or damage, especially to health\",\"74\":\"a person believed to communicate divine knowledge or predictions\",\"77\":\"a worker who cuts down trees\",\"86\":\"suitable for a prince; magnificent or lavish\",\"88\":\"extremely unpleasant or objectionable, informal\",\"95\":\"engaged in deep and prolonged reflection\",\"105\":\"handle badly, ineptly or carelessly\",\"106\":\"act or speak clumsily; proceed in a confused manner\",\"110\":\"settle a dispute by acting as an appointed neutral decision-maker\",\"116\":\"having patches of two or more colors, especially on an animal\"}").items()}
checks={int(k):v for k,v in json.loads("{\"31\":\"The provided lemma is 'clove' but the teaching_sense_id encodes cleave; check irregular past-tense form, lemma and intended verb sense before editing.\",\"35\":\"Confirm cleave as base-form verb, and distinguish it from clove (past-tense variant); correct the Sense-KU mapping if needed.\",\"58\":\"Compare adverbial register and overlap of merrily / blithely / happily; revise distractors or give an example with diagnostic usage.\",\"60\":\"Rickety denotes instability due to weak construction; distinguish it from shaky/wobbly by context or replace both.\",\"64\":\"The definition describes translation between languages, not transcription; verify transcriber sense source and correct the definition or sense mapping before proposing options.\",\"67\":\"Check abstention (a specific act/choice of not participating) versus abstinence (sustained self-denial); current clue overlaps.\",\"72\":\"Coda is a concluding passage of a musical work; finale may refer more broadly to the last movement/section. Verify the intended music-theory sense.\",\"78\":\"Testis is the anatomical term, testicle a common synonym. Replace one distractor rather than inventing a narrower biological definition.\",\"83\":\"Deliverance and saving are close in this source sense; confirm whether spiritual vs physical context differentiates them.\",\"93\":\"Dour can mean stern or gloomy, rather than simply unyielding. Check sense alignment and revise distractor.\",\"100\":\"Forebear/forbear are historical spelling variants for ancestor; do not use them as mutual distractors. Verify variant labeling.\",\"107\":\"Earlier and sooner refer to different temporal frames but both fit a loose comparative clue; use natural example sentences.\",\"109\":\"Sooner and earlier can overlap; add future-relative timing contrast in an example before deciding.\",\"111\":\"Queasy typically means nauseated, whereas loathsome may mean nausea-inducing. Verify adjective Sense and subject role.\",\"112\":\"Deadpan often involves deliberately impassive facial expression/humor; expressionless is broader. Verify intended usage.\"}").items()}
assert len(cases)==53 and len(clues)==38 and len(checks)==15
result=[]
for item in cases:
 n=item["review_number"];is_context=item["category"]=="contextual_disambiguation"
 assert n in (clues if is_context else checks)
 result.append({"review_number":n,"ku_id":item["ku_id"],"source":item["source"],"source_line":item["source_line"],"answer":item["answer"],"competing_options":item["competing_options"],"original_definition":item["definition_en"],"action_type":"REWRITE_DEFINITION_CANDIDATE" if is_context else "VERIFY_LEXICAL_SENSE_FIRST","proposed_definition":clues[n] if is_context else None,"lexical_review_instruction":checks[n] if not is_context else None,"status":"EDITORIAL_CANDIDATE_NOT_CERTIFIED","source_modified":False,"warning":"Not approved. New definition must be checked for answer uniqueness against the full options and original Sense."})
result.sort(key=lambda x:x["review_number"])
assert len(result)==53 and len({x["ku_id"] for x in result})==53
(D/"curated_remaining_53.jsonl").write_text("".join(json.dumps(x,ensure_ascii=False)+"\n" for x in result),encoding="utf-8")
summary={"records":53,"context_definition_candidates":38,"lexical_sense_verification_plans":15,"source_modified":False,"semantic_certified":False,"ready_for_runtime":False}
(D/"curated_remaining_53_summary.json").write_text(json.dumps(summary,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
print(json.dumps(summary))
